# Custom exception hierarchy with structured data
class UploadError(Exception):
    '''Base class for upload pipeline errors.'''

class MissingColumnsError(UploadError):
    def __init__(self, missing: set[str], report_type: str):
        self.missing = missing
        self.report_type = report_type
        super().__init__(f"{report_type}: missing columns {sorted(missing)}")

def validate(columns: list[str], required: set[str], report_type: str) -> None:
    missing = required - set(columns)
    if missing:
        raise MissingColumnsError(missing, report_type)

try:
    validate(["sku"], {"sku", "qty"}, "inventory")
except MissingColumnsError as e:
    print(e.missing)          # {'qty'}
```

