# Exception chaining and notes: translate low-level errors with context
import json

class ConfigError(Exception): ...

def load_config(path: str) -> dict:
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError as e:
        raise ConfigError(f"config not found: {path}") from e
    except json.JSONDecodeError as e:
        e.add_note(f"while parsing {path}")   # 3.11+
        raise                                  # re-raise original with note
