# Boundary handler: log once, record status, return a clean response
import logging
logger = logging.getLogger(__name__)

def handler(event, context):
    upload_id = event.get("upload_id")
    try:
        process(upload_id)
    except UploadError as e:                 # expected, user-facing failure
        logger.warning("upload %s failed: %s", upload_id, e)
        set_status(upload_id, "Error", str(e))
        return {"statusCode": 422, "body": str(e)}
    except Exception:                         # unexpected bug
        logger.exception("unexpected failure for upload %s", upload_id)
        set_status(upload_id, "Error", "internal error")
        return {"statusCode": 500, "body": "internal error"}
    set_status(upload_id, "Completed")
    return {"statusCode": 200, "body": "ok"}
